from decimal import Decimal


def line_total(lines):
    x = 0
    for line in lines:
        x += line["quantity"] * line["unit_cents"]
    return x


def tax_for(amount_cents, rate):
    """Tax in integer cents for amount_cents at rate (e.g. "0.0825" for 8.25%).

    Rounds with banker's rounding (ROUND_HALF_EVEN) per the finance decision.
    """
    if isinstance(rate, float):
        rate = repr(rate)
    tax = Decimal(amount_cents) * Decimal(rate)
    return int(tax.quantize(Decimal(1), rounding=ROUND_HALF_EVEN))
